package com.chondrimaishrat.elearning.assignment;
import com.chondrimaishrat.elearning.user.UserAccount; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="assignment_submissions",uniqueConstraints=@UniqueConstraint(columnNames={"assignment_id","student_id"})) public class AssignmentSubmission {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="assignment_id") private Assignment assignment; @ManyToOne(optional=false) @JoinColumn(name="student_id") private UserAccount student; @Column(nullable=false,length=1000) private String submissionLink; private Integer grade; @Column(length=1000) private String feedback; private LocalDateTime submittedAt; protected AssignmentSubmission(){} public AssignmentSubmission(Assignment a,UserAccount s,String link){assignment=a;student=s;submissionLink=link;submittedAt=LocalDateTime.now();} public Long getId(){return id;} public Assignment getAssignment(){return assignment;} public UserAccount getStudent(){return student;} public String getSubmissionLink(){return submissionLink;} public Integer getGrade(){return grade;} public String getFeedback(){return feedback;} public void grade(int g,String f){grade=g;feedback=f;}}
